sql_query:
SELECT "Primary endpoint"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Primary endpoint", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Head and Neck' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Primary endpoint" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Primary endpoint", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Head and Neck' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_endpoint_components(source_value) AS "components"
FROM base;
